window.ANGI_PROMPT = (target, method) => {
  const profiles = window.ANGI_INSTALL_PROFILES;
  const id = typeof target === 'string' ? target : target?.id;
  if (!Object.hasOwn(profiles, id)) return 'Stop. This target has no install profile.';
  const profile = profiles[id];
  const mode = method ?? Object.keys(profile.modes)[0];
  if (!Object.hasOwn(profile.modes, mode)) return 'Stop. This deployment method is unavailable.';
  const details = profile.modes[mode];
  const values = {...profile, ...details, sourceRef: angiSourceRef, medium: details.label};
  return angiSourceTemplate.replace(/{{(\w+)}}/g, (_, key) => values[key]);
};
